### RAJA version

```cpp
// vector_add_raja.cpp
#include <RAJA/RAJA.hpp>
#include <iostream>
#include <vector>

int main()
{
    constexpr int N = 1<<20;          // 1M elements
    std::vector<float> h_A(N), h_B(N), h_C(N);

    for (int i=0;i<N;i++) { h_A[i] = i; h_B[i] = 2*i; }

    // Allocate device memory
    float *d_A, *d_B, *d_C;
    RAJA::cuda_malloc(&d_A, N*sizeof(float));
    RAJA::cuda_malloc(&d_B, N*sizeof(float));
    RAJA::cuda_malloc(&d_C, N*sizeof(float));

    // Copy to device
    RAJA::cuda_memcpy(d_A, h_A.data(), N*sizeof(float), RAJA::cudaMemcpyHostToDevice);
    RAJA::cuda_memcpy(d_B, h_B.data(), N*sizeof(float), RAJA::cudaMemcpyHostToDevice);

    // Policy: launch a CUDA kernel with 256 threads per block
    constexpr int blockSize = 256;
    RAJA::forall<RAJA::cuda_exec<blockSize>>(
        RAJA::RangeSegment(0, N),
        [=] RAJA_DEVICE (int i) {
            d_C[i] = d_A[i] + d_B[i];
        });

    // Copy back
    RAJA::cuda_memcpy(h_C.data(), d_C, N*sizeof(float), RAJA::cudaMemcpyDeviceToHost);
    RAJA::cuda_device_synchronize();

    // Verify
    for (int i=0;i<N;i++)
        if (h_C[i] != h_A[i] + h_B[i]) {
            std::cout << "mismatch at " << i << "\n";
            break;
        }

    // Free
    RAJA::cuda_free(d_A); RAJA::cuda_free(d_B); RAJA::cuda_free(d_C);
    return 0;
}
```

Compile & run:

```bash
# Using nvcc
nvcc -O3 -std=c++17 vector_add_raja.cpp -lRAJA -lcudart -o vecadd_raja
./vecadd_raja
```

> **Why it works**  
> * `RAJA::cuda_exec<blockSize>` tells RAJA to launch a CUDA kernel with the given block size.  
> * The lambda is marked `RAJA_DEVICE` so it can be compiled for the device.  
> * RAJA automatically generates the kernel launch code that maps the loop index `i` to the CUDA thread index (`blockIdx.x * blockDim.x + threadIdx.x`).  
> * The same code will run on the CPU if you change the policy to `RAJA::loop_exec` (or `RAJA::omp_parallel_for_exec` for OpenMP).

