### RAJA version

```cpp
// stencil_raja.cpp
#include <RAJA/RAJA.hpp>
#include <iostream>
#include <vector>

int main()
{
    constexpr int nx = 512, ny = 512;
    const size_t sz = nx*ny*sizeof(float);

    std::vector<float> h_in(nx*ny), h_out(nx*ny);

    // initial condition
    for (int j=0;j<ny;j++)
        for (int i=0;i<nx;i++)
            h_in[j*nx+i] = (i==nx/2 && j==ny/2) ? 1.0f : 0.0f;

    // device memory
    float *d_in, *d_out;
    RAJA::cuda_malloc(&d_in, sz);
    RAJA::cuda_malloc(&d_out, sz);

    RAJA::cuda_memcpy(d_in, h_in.data(), sz, RAJA::cudaMemcpyHostToDevice);

    // 2‑D range: rows (j) and columns (i)
    RAJA::forall<RAJA::cuda_exec<16,16>>(
        RAJA::RangeSegment(0, ny),   // rows
        RAJA::RangeSegment(0, nx),   // columns
        [=] RAJA_DEVICE (int j, int i) {
            if (i > 0 && i < nx-1 && j > 0 && j < ny-1) {
                int idx = j*nx + i;
                d_out[idx] = 0.25f * ( d_in[idx-1] + d_in[idx+1] +
                                       d_in[idx-nx] + d_in[idx+nx] );
            }
        });

    RAJA::cuda_memcpy(h_out.data(), d_out, sz, RAJA::cudaMemcpyDeviceToHost);
    RAJA::cuda_device_synchronize();

    // verify a few points
    std::cout << "center value: " << h_out[(ny/2)*nx + nx/2] << "\n";

    RAJA::cuda_free(d_in); RAJA::cuda_free(d_out);
    return 0;
}
```

Compile & run:

```bash
nvcc -O3 -std=c++17 stencil_raja.cpp -lRAJA -lcudart -o stencil_raja
./stencil_raja
```

> **Explanation**  
> * `RAJA::cuda_exec<16,16>` creates a 2‑D CUDA launch configuration with 16×16 threads per block.  
> * The outer `forall` takes two `RangeSegment`s, one for each dimension.  
> * The lambda receives the loop indices `(j,i)` exactly as the CUDA kernel would.  
> * RAJA handles the mapping to `blockIdx`, `threadIdx`, and the 2‑D grid automatically.  
> * Switching to CPU is as simple as changing the policy to `RAJA::loop_exec` (or `RAJA::omp_parallel_for_exec`).

